    <div style="background:#1e293b;padding:20px;border-radius:12px;margin-bottom:20px;border:1px solid #334155;">
    <h3 style="color:#93c5fd;margin-top:0;">👩🏾‍🏫 Teacher Explanation</h3>
    <p>Say “sheep” and then “cheap”. Can you hear the difference? The first sound in <strong>sheep</strong> is <strong>/ʃ/</strong> — a long, soft hushing sound, like telling someone to be quiet: “shhh”. The first sound in <strong>cheap</strong> is <strong>/tʃ/</strong> — a short, sharp sound that starts with your tongue touching the roof of your mouth, like a sneeze: “atchoo!”</p>
    <p>Words that differ in only one sound are called <strong>minimal pairs</strong>: ship/chip, shop/chop, sheep/cheap, wash/watch.</p>
    <div style="background:#172554;border-left:4px solid #60a5fa;padding:14px 16px;border-radius:9px;margin:14px 0;">
    <p style="margin:0 0 6px 0;color:#bfdbfe;font-weight:bold;">🗣️ In Simple Words</p>
    <div>/ʃ/ = long and soft (shhh). /tʃ/ = short and sharp (ch!).</div>
    </div>
    </div>
