    <div style="background:#1e293b;padding:20px;border-radius:12px;margin-bottom:20px;border:1px solid #334155;">
    <h3 style="color:#93c5fd;margin-top:0;">👩🏾‍🏫 Teacher Explanation</h3>
    <p>The <strong>main idea</strong> is what a text is mostly about — the big message. <strong>Specific details</strong> are the small facts that support it: names, numbers, places, times and reasons.</p>
    <p>To listen well: (1) listen to the whole text once for the main idea; (2) listen again and note details using <strong>who, what, where, when, why, how many</strong>; (3) check your notes.</p>
    <div style="background:#172554;border-left:4px solid #60a5fa;padding:14px 16px;border-radius:9px;margin:14px 0;">
    <p style="margin:0 0 6px 0;color:#bfdbfe;font-weight:bold;">🗣️ In Simple Words</p>
    <div>Main idea = the big message. Details = the small facts.</div>
    </div>
    </div>
